# সাধারণ গণিত অধ্যায় ১১ (বীজগণিতীয় অনুপাত ও সমানুপাত): পাঠ্যবইয়ের ৫ নং সৃজনশীল (হুবহু) এবং
# ৬ নং সংক্ষিপ্ত-উত্তর প্রশ্নের ক–ঘ (হুবহু, c10_11.json এর শেষে b61–b64)। উত্তর কোডে যাচাই করা
import json, os
from fractions import Fraction as F
from math import gcd
from sympy import symbols, factor, expand
a=symbols('a'); x,y,z=symbols('x y z')
assert F(400*90//100,400)==F(9,10)
assert (lambda A:(A,A*5))(10)==(10,50) and F(10-5,40+5)==F(1,9)
assert 336*F(3,2)*F(5,4)==630
assert gcd(20,28)==4 and 20*28//4==140
assert factor(expand((x**2+y**2)*z-x*(y**2+z**2)))==factor((x-z)*(x*z-y**2))
assert F(700,1000)==F(7,10) and (6,8,12)==(3*2,4*2,6*2)
HERE=os.path.dirname(os.path.abspath(__file__))
CQ=[{'n':'b1','ex':'11.1','lv':'মধ্যম',
 'stem':'দৃশ্যকল্প ১: একদিন কোনো শ্রেণিতে অনুপস্থিত ও উপস্থিত শিক্ষার্থীদের সংখ্যার অনুপাত 1 : 4। ওই দিন আরও 5 জন শিক্ষার্থী বেশি উপস্থিত থাকলে অনুপস্থিত ও উপস্থিত শিক্ষার্থীদের সংখ্যার অনুপাত হতো 1 : 9\nদৃশ্যকল্প ২: একটি আয়তাকার জমির ক্ষেত্রফল 336 বর্গ একক। জমিটির দৈর্ঘ্য ও প্রস্থের সাথে অপর একটি আয়তাকার জমির দৈর্ঘ্য ও প্রস্থের অনুপাত যথাক্রমে 2 : 3 এবং 4 : 5',
 'p':['একটি দ্রব্য 400 টাকায় ক্রয় করে 10% ক্ষতিতে বিক্রয় করলে বিক্রয়মূল্য ও ক্রয়মূল্যের অনুপাত নির্ণয় করো।','দৃশ্যকল্প ১ এ উল্লেখিত শ্রেণির শিক্ষার্থী সংখ্যা নির্ণয় করো।','দৃশ্যকল্প ২ এ উল্লেখিত ২য় জমিটির ক্ষেত্রফল নির্ণয় করো।'],
 'a':'ক) বিক্রয়মূল্য 360 টাকা ⇒ 360 : 400 = 9 : 10\nখ) অনুপস্থিত x, উপস্থিত 4x ⇒ (x − 5) : (4x + 5) = 1 : 9 ⇒ x = 10 ⇒ মোট 50 জন\nগ) ২য় জমির দৈর্ঘ্য = (3/2) × ১ম জমির দৈর্ঘ্য, প্রস্থ = (5/4) × ১ম জমির প্রস্থ ⇒ ক্ষেত্রফল = 336 × 15/8 = 630 বর্গ একক'}]
json.dump(CQ,open(os.path.join(HERE,'cq_c10_11.json'),'w'),ensure_ascii=False,indent=1)
SQ=[('দুইটি সংখ্যার অনুপাত 5 : 7 এবং এদের গ.সা.গু. 4 হলে, সংখ্যা দুইটির ল.সা.গু. কত?','সংখ্যা দুইটি 5x ও 7x, গ.সা.গু. x = 4 ⇒ সংখ্যা 20 ও 28 ⇒ ল.সা.গু. = 140','সহজ'),
('(x² + y²)/(y² + z²) = x/z এবং z ≠ x হলে, দেখাও যে, x, y ও z ক্রমিক সমানুপাতী।','(x² + y²)z = x(y² + z²) ⇒ (x − z)(xz − y²) = 0 ; z ≠ x ⇒ y² = xz ⇒ x : y = y : z (প্রমাণিত)','মধ্যম'),
('এক ঘন সে.মি. কাঠের ভর 700 মিলিগ্রাম হলে, সমআয়তনের কাঠের ভর ও পানির ভরের অনুপাত নির্ণয় করো।','এক ঘন সে.মি. পানির ভর 1 গ্রাম = 1000 মিলিগ্রাম ⇒ 700 : 1000 = 7 : 10','সহজ'),
('x : y = 3 : 4 এবং y : z = 2 : 3 হলে, দেখাও যে, x/3 = y/4 = z/6','x : y = 6 : 8, y : z = 8 : 12 ⇒ x : y : z = 6 : 8 : 12 = 3 : 4 : 6 ⇒ x/3 = y/4 = z/6 (প্রমাণিত)','সহজ')]
p=os.path.join(HERE,'c10_11.json'); cur=json.load(open(p,encoding='utf-8')); cur=[q for q in cur if int(q['n'][1:])<=60]; assert len(cur)==60
for i,(q,a_,lv) in enumerate(SQ): cur.append({'n':f'b{61+i}','q':q,'a':a_,'lv':lv,'ex':'11.1'})
json.dump(cur,open(p,'w',encoding='utf-8'),ensure_ascii=False,indent=1); print('cq 1, sq +4')
